<script>
  import {onDestroy} from 'svelte';import {client,jobs,trackJob,demoPath,changed,isAbort} from '../lib/api.js';import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';
  export let table;export let lang='vi';let overwrite=false,reviewed=false,selected=[],seen='',busy='',error='',success='',alive=true;
  $: t=(vi,en)=>lang==='en'?en:vi;
  $: job=$jobs[table.slug];$: running=job&&['queued','running'].includes(job.status);
  $: proposals=job?.kind==='enrich'&&job.status==='done'?job.result?.proposals:null;
  $: if(proposals&&job.id!==seen){seen=job.id;selected=proposals.map(p=>p.product_id);}
  async function run(){if(busy||running)return;busy='run';error='';success='';try{const result=await client.mutate(`${table.slug}:enrich`,()=>client.request(`${demoPath(table.slug)}/enrich`,{method:'POST',body:{dry_run:true,overwrite_fields:overwrite?['aliases','use_cases','sample_questions']:[]}}));trackJob(table.slug,result.job_id);}catch(e){if(alive&&!isAbort(e))error=e.message;}finally{if(alive)busy='';}}
  async function apply(){if(busy||!selected.length)return;busy='apply';error='';try{const result=await client.mutate(`${table.slug}:apply-enrich:${job.id}`,()=>client.request(`${demoPath(table.slug)}/enrich/${job.id}/apply`,{method:'POST',body:{accept_product_ids:selected,mark_reviewed:reviewed}}));changed(table.slug,result);if(alive)success=t(`Đã lưu ${result.applied} đề xuất.`,`Saved ${result.applied} proposals.`);}catch(e){if(alive&&!isAbort(e))error=e.message;}finally{if(alive)busy='';}}
  onDestroy(()=>alive=false);
</script>
<section class="panel"><h2>{t('Bổ sung dữ liệu bằng AI','Enrich data with AI')}</h2><p class="text-muted text-sm mt-2 mb-6">{t('Đề xuất tên gọi khác, nhu cầu sử dụng và câu hỏi mẫu. Bạn xem và chọn trước khi lưu.','Suggest aliases, use cases and sample questions. Review and select proposals before saving.')}</p><div class="flex flex-wrap gap-4 items-center"><Button variant="primary" busy={busy==='run'} disabled={!!busy||running} on:click={run}><Icon name="spark" size={17}/>{t('Tạo đề xuất','Generate proposals')}</Button><label class="flex items-center gap-2 text-xs"><input type="checkbox" bind:checked={overwrite}/>{t('Cho phép cập nhật trường đã có','Update existing fields')}</label></div></section><Notice {error} {success} {lang}/>
{#if proposals}<section class="panel mt-5"><div class="flex flex-wrap items-center gap-4"><h2>{proposals.length} {t('đề xuất','proposals')}</h2><label class="flex items-center gap-2 text-xs sm:ml-auto"><input type="checkbox" bind:checked={reviewed}/>{t('Đánh dấu đã duyệt','Mark reviewed')}</label><Button variant="primary" busy={busy==='apply'} disabled={!selected.length||!!success} on:click={apply}>{t('Lưu mục đã chọn','Save selected')} ({selected.length})</Button></div>{#each proposals as proposal}<div class="border-t border-line mt-5 pt-5"><label class="flex items-center gap-3 font-semibold"><input type="checkbox" value={proposal.product_id} bind:group={selected}/>{proposal.name}</label>{#each Object.entries(proposal.changes) as [field,value]}<div class="ml-7 mt-4"><p class="text-xs text-muted mb-2">{({aliases:t('Tên gọi khác','Aliases'),use_cases:t('Nhu cầu sử dụng','Use cases'),sample_questions:t('Câu hỏi mẫu','Sample questions')})[field]||field}</p><div class="flex flex-wrap gap-2">{#each value.new as item}<span class="badge">{item}</span>{/each}</div></div>{/each}</div>{:else}<div class="empty">{t('Không có đề xuất mới.','No new proposals.')}</div>{/each}</section>{/if}
